import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;
    static final int MAXN = 20;

    static int pow(int a, int b) {
        long ans = 1;
        long base = a % MOD;
        while (b > 0) {
            if ((b & 1) == 1) ans = (ans * base) % MOD;
            base = (base * base) % MOD;
            b >>= 1;
        }
        return (int) ans;
    }

    static int inv(int a) { return pow(a, MOD - 2); }

    static int popcount(int x) { return Integer.bitCount(x); }

    static int ctz(int x) { return Integer.numberOfTrailingZeros(x); }

    static int reduce(int x) {
        if (x >= MOD) x -= MOD;
        else if (x < 0) x += MOD;
        return x;
    }

    static boolean next_permutation(int[] a) {
        int i = a.length - 2;
        while (i >= 0 && a[i] >= a[i + 1]) i--;
        if (i < 0) return false;
        int j = a.length - 1;
        while (a[j] <= a[i]) j--;
        int tmp = a[i];
        a[i] = a[j];
        a[j] = tmp;
        for (int l = i + 1, r = a.length - 1; l < r; l++, r--) {
            tmp = a[l];
            a[l] = a[r];
            a[r] = tmp;
        }
        return true;
    }

    static void fwt(int[] a, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            int val = a[i] + a[i + lim] - MOD;
            a[i] = reduce(val);
        }
        fwt(a, lim);
        fwt(Arrays.copyOfRange(a, lim, a.length), lim);
        // Actually the original passes two pointers: fwt(a,lim) and fwt(a+lim,lim)
        // We need to modify in place: after first call, second call works on the second half.
        // We'll call on the same array but with offsets using index.
        // Better to implement iterative or use helper with start index.
    }

    static void fwt2(int[] a, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            int val = a[i] - a[i + lim];
            a[i] = reduce(val);
        }
        fwt2(a, lim);
        fwt2(Arrays.copyOfRange(a, lim, a.length), lim);
    }

    // Custom implementation to handle both halves in one array
    static void fwt(int[] a, int start, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            int idx1 = start + i;
            int idx2 = start + i + lim;
            int val = a[idx1] + a[idx2] - MOD;
            a[idx1] = reduce(val);
        }
        fwt(a, start, lim);
        fwt(a, start + lim, lim);
    }

    static void fwt2(int[] a, int start, int lim) {
        if ((lim /= 2) == 0) return;
        for (int i = 0; i < lim; ++i) {
            int idx1 = start + i;
            int idx2 = start + i + lim;
            int val = a[idx1] - a[idx2];
            a[idx1] = reduce(val);
        }
        fwt2(a, start, lim);
        fwt2(a, start + lim, lim);
    }

    static int fac(int x) {
        return x == 0 ? 1 : fac(x - 1) * x;
    }

    static int C(int n, int m) {
        return fac(n) / fac(m) / fac(n - m);
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        int[][] a = new int[n][n];
        int inv100 = inv(100);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int x = in.nextInt();
                a[i][j] = (int) ((long) x * inv100 % MOD);
            }
        }
        int[] b = new int[n * n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                b[i * n + j] = a[i][j];
            }
        }

        int[] tot = new int[MAXN];
        int[] mp = new int[1 << n];
        ArrayList<Integer>[] v = new ArrayList[MAXN];
        for (int i = 0; i < MAXN; i++) v[i] = new ArrayList<>();
        for (int i = 0; i < (1 << n); i++) {
            int pc = popcount(i);
            v[pc].add(i);
            mp[i] = tot[pc]++;
        }

        int m = n / 2;
        int M = n - m;

        // Precompute size for f and g arrays
        int sizeF = 1 << tot[m];
        int[] f = new int[sizeF];
        int[] g = new int[sizeF];

        // First half
        int lim1 = 1 << (m * n);
        for (int i = 0; i < lim1; i++) {
            long p = 1;
            for (int j = 0; j < m * n; j++) {
                int bit = (i >> j) & 1;
                p = (p * (bit == 1 ? b[j] : MOD + 1 - b[j])) % MOD;
            }
            int[] S = new int[m];
            for (int j = 0; j < m; j++) {
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for (int mask : v[m]) {
                int[] s = new int[m];
                int t = 0;
                for (int k = mask; k != 0; k &= k - 1) {
                    s[t++] = ctz(k);
                }
                Arrays.sort(s);
                do {
                    boolean ok = true;
                    for (int j = 0; j < m; j++) {
                        if (((S[j] >> s[j]) & 1) == 0) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        st |= 1 << mp[mask];
                        break;
                    }
                } while (next_permutation(s));
            }
            f[st] = reduce((int) (f[st] + p));
        }

        // Second half
        int lim2 = 1 << (M * n);
        for (int i = 0; i < lim2; i++) {
            long p = 1;
            for (int j = 0; j < M * n; j++) {
                int bit = (i >> j) & 1;
                p = (p * (bit == 1 ? b[j + n * m] : MOD + 1 - b[j + n * m])) % MOD;
            }
            int[] S = new int[M];
            for (int j = 0; j < M; j++) {
                S[j] = (i >> (j * n)) & ((1 << n) - 1);
            }
            int st = 0;
            for (int mask : v[n - m]) {
                int[] s = new int[M];
                int t = 0;
                for (int k = mask; k != 0; k &= k - 1) {
                    s[t++] = ctz(k);
                }
                Arrays.sort(s);
                do {
                    boolean ok = true;
                    for (int j = 0; j < M; j++) {
                        if (((S[j] >> s[j]) & 1) == 0) {
                            ok = false;
                            break;
                        }
                    }
                    if (ok) {
                        int complement = (~mask) & ((1 << n) - 1);
                        st |= 1 << mp[complement];
                        break;
                    }
                } while (next_permutation(s));
            }
            g[st] = reduce((int) (g[st] + p));
        }

        // FWT
        fwt(f, 0, sizeF);
        fwt(g, 0, sizeF);
        for (int i = 0; i < sizeF; i++) {
            f[i] = (int) ((long) f[i] * g[i] % MOD);
        }
        fwt2(f, 0, sizeF);

        int ans = 0;
        for (int i = 1; i < sizeF; i++) {
            ans = reduce(ans + f[i]);
        }
        System.out.println(ans);
    }
}
